def parser(log: str) -> dict[str, str]:
    # Improved, robust parser for multiple test output formats (TRX, JUnit, console)
    import re
    import html
    from xml.etree import ElementTree as ET

    def map_outcome(outcome: str) -> str:
        o = (outcome or "").strip().lower()
        # Treat known pass outcomes
        if o in ("pass", "passed", "succeeded", "success"):
            return "pass"
        # Treat known skip outcomes
        if o in (
            "skipped",
            "notexecuted",
            "not executed",
            "notrun",
            "not run",
            "ignored",
            "inconclusive",
            "canceled",
            "cancelled",
        ):
            return "skip"
        # Everything else is considered fail (e.g., Failed, Error, Aborted, TimedOut)
        return "fail"

    results: dict[str, str] = {}

    def tag_local_name(tag: str) -> str:
        if not tag:
            return ""
        if tag.startswith("{"):
            # Strip namespace: {ns}local
            return tag.split("}", 1)[1]
        return tag

    def parse_trx_from_root(root):
        # Collect UnitTestResult nodes regardless of namespace
        for node in root.iter():
            if tag_local_name(node.tag) == "UnitTestResult":
                name = node.attrib.get("testName")
                outcome = node.attrib.get("outcome", "")
                if name:
                    results[name] = map_outcome(outcome)

    def parse_junit_from_root(root):
        # JUnit/TestNG style: <testcase> with <failure>/<error>/<skipped> children
        for tc in root.iter():
            if tag_local_name(tc.tag).lower() == "testcase":
                # Construct a full name if classname and name exist
                name = tc.attrib.get("name") or ""
                classname = tc.attrib.get("classname")
                if classname:
                    full_name = f"{classname}.{name}" if name else classname
                else:
                    full_name = name
                if not full_name:
                    continue
                status = "pass"
                for child in list(tc):
                    ln = tag_local_name(child.tag).lower()
                    if ln in ("failure", "error"):
                        status = "fail"
                        break
                    if ln in ("skipped", "ignore", "ignored"):
                        status = "skip"
                        # leave loop in case failure follows (rare in JUnit)
                results[full_name] = status

    def try_parse_xml(xml_text: str) -> bool:
        try:
            # Remove BOM and surrounding whitespace
            xml_text_clean = xml_text.lstrip("\ufeff").strip()
            root = ET.fromstring(xml_text_clean)
        except Exception:
            return False
        # Try both TRX and JUnit extraction regardless of root element name
        before = len(results)
        parse_trx_from_root(root)
        parse_junit_from_root(root)
        return len(results) > before

    # 1) Try to parse the entire log as XML
    if try_parse_xml(log):
        return results

    # 2) Try to locate and parse a TRX block
    start = log.find("<TestRun")
    end = log.rfind("</TestRun>")
    if start != -1 and end != -1 and end > start:
        trx_xml = log[start : end + len("</TestRun>")]
        if try_parse_xml(trx_xml):
            return results

    # 3) Try to locate and parse JUnit/testsuites block
    # Try <testsuites>...</testsuites>
    start_js = log.find("<testsuites")
    end_js = log.rfind("</testsuites>")
    if start_js != -1 and end_js != -1 and end_js > start_js:
        junit_xml = log[start_js : end_js + len("</testsuites>")]
        if try_parse_xml(junit_xml):
            return results
    # Try <testsuite>...</testsuite>
    start_js = log.find("<testsuite")
    end_js = log.rfind("</testsuite>")
    if start_js != -1 and end_js != -1 and end_js > start_js:
        junit_xml = log[start_js : end_js + len("</testsuite>")]
        if try_parse_xml(junit_xml):
            return results

    # 4) Fallback regex: extract UnitTestResult start tags
    tag_re = re.compile(r"<UnitTestResult\b[^>]*>", re.IGNORECASE)
    name_re = re.compile(r'\btestName="([^"]+)"', re.IGNORECASE)
    outcome_re = re.compile(r'\boutcome="([^"]+)"', re.IGNORECASE)
    any_regex = False
    for m in tag_re.finditer(log):
        tag = m.group(0)
        m_name = name_re.search(tag)
        m_outcome = outcome_re.search(tag)
        if m_name and m_outcome:
            name = html.unescape(m_name.group(1))
            outcome = html.unescape(m_outcome.group(1))
            results[name] = map_outcome(outcome)
            any_regex = True
    if any_regex:
        return results

    # 5) Console/text fallbacks

    # Generic "Passed/Failed/Skipped <name> [time]" pattern (xUnit console style)
    pat_generic = re.compile(
        r"^\s*(Passed|Failed|Skipped)\s+(.+?)\s*(?:\[\s*\d+(?:\.\d+)?\s*(?:ms|s|sec|seconds|m?s)\s*\])?\s*$",
        re.IGNORECASE,
    )
    for line in log.splitlines():
        m = pat_generic.match(line.strip())
        if m:
            status_word, name = m.groups()
            results[name.strip()] = map_outcome(status_word)

    # go test style: --- PASS: TestName, --- FAIL: TestName, --- SKIP: TestName
    pat_go = re.compile(r"^\s*---\s+(PASS|FAIL|SKIP):\s+(.+?)\s*(?:\(|$)", re.IGNORECASE)
    for line in log.splitlines():
        m = pat_go.match(line)
        if m:
            status_word, name = m.groups()
            results[name.strip()] = map_outcome(status_word)

    # pytest style: path::test_name STATUS
    pat_py = re.compile(r"^\s*[\w\/\.\-]+::[^\s]+?\s+(PASSED|FAILED|SKIPPED|ERROR)\b", re.IGNORECASE)
    for line in log.splitlines():
        m = pat_py.match(line)
        if m:
            status_word = m.group(1).lower()
            status = {"passed": "pass", "failed": "fail", "skipped": "skip", "error": "fail"}.get(status_word, "fail")
            # Extract name after '::'
            try:
                name = line.split("::", 1)[1].rsplit(None, 1)[0].strip()
            except Exception:
                continue
            results[name] = status

    return results
